import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Custom fused LayerNorm+GELU+Scaling operator
fused_op_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <math.h>

__global__ void fused_kernel(const float* input, float* output, 
                            int N, int D, int H, int W, int C,
                            float eps, float scaling_factor) {
    extern __shared__ float sdata[];
    int spatial_idx = blockIdx.x;
    int c = threadIdx.x;

    if (spatial_idx >= N*D*H*W || c >= C) return;

    // Calculate original indices
    int n = spatial_idx / (D*H*W);
    int rem = spatial_idx % (D*H*W);
    int d = rem / (H*W);
    rem = rem % (H*W);
    int h = rem / W;
    int w = rem % W;

    // Global memory index
    int idx = ((n*D + d)*H + h)*W + w;
    float x = input[idx*C + c];

    // Shared memory for block reductions
    sdata[c] = x;
    sdata[c + C] = x * x;
    __syncthreads();

    // Parallel reduction for sum and sum of squares
    for(int s = C/2; s>0; s>>=1) {
        if(c < s) {
            sdata[c] += sdata[c + s];
            sdata[c + C] += sdata[c + s + C];
        }
        __syncthreads();
    }

    if(c == 0) {
        float mean = sdata[0] / C;
        float var = sdata[C]/C - mean*mean;
        sdata[0] = mean;
        sdata[1] = rsqrtf(var + eps);
    }
    __syncthreads();

    float normalized = (x - sdata[0]) * sdata[1];
    float gelu = 0.5f * normalized * (1.0f + erff(normalized / 1.41421356237f));
    output[idx*C + c] = gelu * scaling_factor;
}

torch::Tensor fused_forward_cuda(torch::Tensor input, float eps, float scaling_factor) {
    auto sizes = input.sizes();
    int N = sizes[0], D = sizes[2], H = sizes[3], W = sizes[4], C = sizes[1];
    int spatial_size = N*D*H*W;

    auto output = torch::empty_like(input);
    dim3 grid(spatial_size);
    dim3 block(C);

    fused_kernel<<<grid, block, 2*C*sizeof(float)>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        N, D, H, W, C,
        eps,
        scaling_factor
    );

    return output;
}
"""

fused_op_cpp = "torch::Tensor fused_forward_cuda(torch::Tensor input, float eps, float scaling_factor);"

# Compile custom operations
fused_op = load_inline(
    name="fused_op",
    cpp_sources=fused_op_cpp,
    cuda_sources=fused_op_source,
    functions=["fused_forward_cuda"],
    verbose=True
)

class ModelNew(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size, stride, padding, bias=True, eps=1e-5, scaling_factor=1.0):
        super(ModelNew, self).__init__()
        self.conv_transpose = nn.ConvTranspose3d(in_channels, out_channels, kernel_size, 
                                                stride=stride, padding=padding, bias=bias)
        self.eps = eps
        self.scaling_factor = scaling_factor
        self.fused_op = fused_op

    def forward(self, x):
        x = self.conv_transpose(x)
        # Reshape and transpose for channel-last format
        x = x.permute(0, 2, 3, 4, 1).contiguous()  # [N, C, D, H, W] -> [N, D, H, W, C]
        x = self.fused_op.fused_forward_cuda(x, self.eps, self.scaling_factor)
        return x.permute(0, 4, 1, 2, 3).contiguous()  # Back to [N, C, D, H, W]
